INSERT INTO stm_translation (tra_id, tra_eleid, tra_column, tra_lanid, tra_name) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM stm_translation WHERE tra_id = 1) THEN 1 ELSE COALESCE((SELECT MAX(tra_id) FROM stm_translation), 0) + 1 END, ele.lan_id, 'Language.name', lang.lan_id, 'Anglès' FROM stm_language ele JOIN stm_language lang ON lang.lan_shortname = 'ca' WHERE ele.lan_shortname = 'en' AND NOT EXISTS (SELECT 1 FROM stm_translation t WHERE t.tra_eleid = ele.lan_id AND t.tra_column = 'Language.name' AND t.tra_lanid = lang.lan_id) AND COALESCE((SELECT cnf_value FROM stm_conf WHERE cnf_name = 'language.default'), 'en') <> 'ca';
